#!/bin/bash
# =============================================================================
# run_experiments_on_instance.sh
#
# Runs on a Vast.ai instance AFTER the repo is cloned. Called by the onstart
# script generated by vastai_run_experiments.sh.
#
# Assumes: cwd is the repo root, Python/CUDA available, env vars set.
# =============================================================================
set -ex

# --- Install package ---
pip install -e "." 2>&1 | tail -5
pip install langchain-openai langgraph 2>&1 | tail -3 || true

# --- Download worlds from HuggingFace ---
echo "=== Downloading worlds from HuggingFace ==="
python scripts/download_data.py --worlds 2>&1 | tee /workspace/download.log

# --- Verify downloads ---
echo "=== Verifying downloaded files ==="
python -c "
import os, h5py
data_dir = 'data/simulated'
files = sorted(f for f in os.listdir(data_dir) if f.endswith('.h5'))
print(f'Found {len(files)} HDF5 files:')
for f in files:
    path = os.path.join(data_dir, f)
    size_mb = os.path.getsize(path) / (1024*1024)
    try:
        with h5py.File(path, 'r') as hf:
            keys = list(hf.keys())
            print(f'  {f:50s} {size_mb:8.1f} MB  keys={keys}')
    except Exception as e:
        print(f'  {f:50s} {size_mb:8.1f} MB  ERROR: {e}')
"

# --- Create experiment configs dynamically ---
echo "=== Creating experiment configs ==="
python - << 'PYEOF'
import yaml, os

WORLDS_ALL = [
    "srtio3_clustered_easy", "srtio3_clustered_medium", "srtio3_clustered_hard",
    "batio3_interface_easy", "batio3_interface_medium", "batio3_interface_hard",
    "sige_gradient_clustered_easy", "sige_gradient_clustered_medium", "sige_gradient_clustered_hard",
]
WORLDS_BATIO3 = [w for w in WORLDS_ALL if w.startswith("batio3")]
WORLDS_SIGE = [w for w in WORLDS_ALL if w.startswith("sige")]
WORLDS_MEDIUM = [w for w in WORLDS_ALL if "medium" in w]

data_dir = "data/simulated"
available = {f.replace(".h5", "") for f in os.listdir(data_dir) if f.endswith(".h5")}
def filter_avail(worlds):
    return [w for w in worlds if w in available]

AGENTS_ALL = ["random", "raster", "gp_ucb", "gp_ucb_equipped", "raster_equipped",
              "stem_agent", "no_planner", "no_uncertainty", "rule_planner", "llm_planner"]
AGENTS_ABLATION = ["stem_agent", "no_planner", "no_uncertainty", "rule_planner", "llm_planner"]
AGENTS_SCALING = ["random", "raster_equipped", "gp_ucb_equipped", "stem_agent"]

configs = {
    "difficulty_scaling": {
        "name": "difficulty_scaling",
        "agents": AGENTS_SCALING,
        "tasks": ["defect_census", "phase_mapping"],
        "worlds": filter_avail(WORLDS_BATIO3),
        "seeds": 5, "budget": 5000.0, "max_steps": 200,
        "score_every_n_acquires": 5,
        "output": "results/difficulty_scaling.json",
    },
    "ablation_study": {
        "name": "ablation_study",
        "agents": AGENTS_ABLATION,
        "tasks": ["defect_census", "phase_mapping", "targeted"],
        "worlds": filter_avail(WORLDS_MEDIUM),
        "seeds": 5, "budget": 5000.0, "max_steps": 200,
        "score_every_n_acquires": 5,
        "output": "results/ablation_study.json",
    },
    "main_targeted": {
        "name": "main_targeted",
        "agents": AGENTS_ALL,
        "tasks": ["targeted"],
        "worlds": filter_avail(WORLDS_SIGE),
        "seeds": 5, "budget": 5000.0, "max_steps": 200,
        "score_every_n_acquires": 5,
        "output": "results/main_targeted.json",
    },
    "main_defect_census": {
        "name": "main_defect_census",
        "agents": AGENTS_ALL,
        "tasks": ["defect_census"],
        "worlds": filter_avail(WORLDS_ALL),
        "seeds": 5, "budget": 5000.0, "max_steps": 200,
        "score_every_n_acquires": 5,
        "output": "results/main_defect_census.json",
    },
    "main_phase_mapping": {
        "name": "main_phase_mapping",
        "agents": AGENTS_ALL,
        "tasks": ["phase_mapping"],
        "worlds": filter_avail(WORLDS_BATIO3),
        "seeds": 5, "budget": 5000.0, "max_steps": 200,
        "score_every_n_acquires": 5,
        "output": "results/main_phase_mapping.json",
    },
}

os.makedirs("experiments/configs", exist_ok=True)
for name, cfg in configs.items():
    if not cfg["worlds"]:
        print(f"  SKIP {name}: no worlds available")
        continue
    n_episodes = len(cfg["agents"]) * len(cfg["worlds"]) * len(cfg["tasks"]) * cfg["seeds"]
    path = f"experiments/configs/{name}.yaml"
    with open(path, "w") as f:
        yaml.dump(cfg, f, default_flow_style=False, sort_keys=False)
    print(f"  {name}: {n_episodes} episodes -> {path}")
PYEOF

# --- Run experiments ---
echo "=== Running experiments ==="
mkdir -p results

CONFIGS=(
    "difficulty_scaling"
    "ablation_study"
    "main_targeted"
    "main_defect_census"
    "main_phase_mapping"
)

for cfg in "${CONFIGS[@]}"; do
    CONFIG_FILE="experiments/configs/${cfg}.yaml"
    if [[ ! -f "$CONFIG_FILE" ]]; then
        echo "SKIP: $CONFIG_FILE not found"
        continue
    fi
    echo ""
    echo "================================================================"
    echo "  RUNNING: $cfg"
    echo "================================================================"
    python -m experiments.run_benchmark run --config "$CONFIG_FILE" 2>&1 \
        | tee "/workspace/${cfg}.log"
    echo "  DONE: $cfg -> results/${cfg}.json"
done

echo ""
echo "=== ALL EXPERIMENTS COMPLETE ==="
echo ""
ls -lh results/*.json
touch /workspace/DONE
